const PartialTradeDetails = z.object({
  settlement_info: z.object({ date: z.string() }),
  instrument: z.null().optional(),
});

const TradeResponseSchema = z.discriminatedUnion('status', [
  z.object({
    status: z.literal('COMPLETE'),
    payload: z.object({ trade_details: FullTradeDetails }),
  }),
  z.object({
    status: z.literal('PARTIAL'),
    payload: z.object({ trade_details: PartialTradeDetails }),
  }),
]);

async function processTradeData(tradeId: string) {
  const response = await fetch(`https://legacy-bank.internal/api/trades/${tradeId}`);
  const result = TradeResponseSchema.safeParse(await response.json());

  if (!result.success) throw new Error('Invalid API response');

  const { status, payload } = result.data;

  if (status === 'COMPLETE') {
    // TypeScript knows instrument exists here
    const { instrument } = payload.trade_details;
    console.log(instrument.type === 'EQUITY' ? instrument.ticker : instrument.cusip);
  } else {
    // TypeScript knows instrument might be null/undefined here
    console.log('Trade data is incomplete; skipping instrument processing');
  }

  return payload;
}
```

By tying the existence of `instrument` to the `status` field, you eliminate the need for `any` while avoiding the 'everything is optional' pattern. This ensures that you only attempt to access the instrument data when the API explicitly confirms the record is `COMPLETE`.

