class SecurityPatternMatcher(PatternMatcher):
    def match(self, line: str) -> Dict[str, str]:
        if "authentication failed" in line.lower():
            return {"priority": "CRITICAL", "facility": "security"}
        elif "brute force" in line.lower() or "unauthorized" in line.lower():
            return {"priority": "ERROR", "facility": "security"}
        elif "SSL certificate" in line:
            return {"priority": "WARNING", "facility": "security"}
        else:
            # Fall back to default behavior
            return DefaultPatternMatcher().match(line)

