class DatabaseDepartmentValidator implements DepartmentValidator {
    private Connection conn;

    public DatabaseDepartmentValidator(Connection conn) {
        this.conn = conn;
    }

    public boolean isValidDepartment(String department) {
        try {
            PreparedStatement ps = conn.prepareStatement("SELECT 1 FROM departments WHERE name = ?");
            ps.setString(1, department);
            ResultSet rs = ps.executeQuery();
            return rs.next();
        } catch (Exception e) {
            return false;
        }
    }
}

